<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Integration: Neural Flora</title>
  <script>p5.disableFriendlyErrors = true;</script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.11.3/p5.min.js"></script>
  <style>
    html, body { margin: 0; padding: 0; overflow: hidden; background: #000; }
    canvas { display: block; }
  </style>
</head>
<body>
<script>
// === Configuration ===
const CONFIG = {
  seed: 888,
  growthRate: 0.5,
  maxNodes: 120,
  connectionThreshold: 150,
  floatSpeed: 0.002,
};

// === Color Palette ===
const PALETTE = {
  midnight: '#050508', // Midnight Black
  burgundy: '#4a0e0e', // Deep Burgundy
  gold: '#d4af37',     // Gold
  accentGold: '#ffdf00' // Bright Gold
};

let nodes = [];
let bgLayer;

function setup() {
  createCanvas(windowWidth, windowHeight);
  randomSeed(CONFIG.seed);
  noiseSeed(CONFIG.seed);

  bgLayer = createGraphics(width, height);
  bgLayer.background(PALETTE.midnight);
  bgLayer.noStroke();

  // Create a deep radial gradient for the background
  for (let r = width; r > 0; r -= 2) {
    let inter = map(r, 0, width, 0, 255);
    bgLayer.fill(5, 5, 15, inter * 0.01);
    bgLayer.ellipse(width/2, height/2, r * 2);
  }

  // Initialize seed nodes
  for (let i = 0; i < 5; i++) {
    nodes.push(new Node(random(width), random(height), true));
  }
}

function draw() {
  image(bgLayer, 0, 0);

  // Symbiotic growth: nodes multiply and connect
  if (nodes.length < CONFIG.maxNodes && frameCount % 60 === 0) {
    let parent = random(nodes);
    nodes.push(new Node(parent.pos.x, parent.pos.y, false));
  }

  // Draw connections first (the Neural Network)
  strokeWeight(0.5);
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      let d = dist(nodes[i].pos.x, nodes[i].pos.y, nodes[j].pos.x, nodes[j].pos.y);
      if (d < CONFIG.connectionThreshold) {
        let alpha = map(d, 0, CONFIG.connectionThreshold, 150, 0);
        stroke(PALETTE.burgundy); 
        strokeWeight(map(d, 0, CONFIG.connectionThreshold, 1.5, 0.2));
        line(nodes[i].pos.x, nodes[i].pos.y, nodes[j].pos.x, nodes[j].pos.y);
      }
    }
  }

  // Draw nodes (the Flora)
  for (let node of nodes) {
    node.update();
    node.display();
  }
}

class Node {
  constructor(x, y, isRoot) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(0.2, 0.8));
    this.size = isRoot ? random(4, 7) : random(2, 5);
    this.angle = random(TWO_PI);
    this.phase = random(TWO_PI);
    this.isRoot = isRoot;
  }

  update() {
    // Organic drifting motion
    let n = noise(this.pos.x * 0.005, this.pos.y * 0.005, frameCount * CONFIG.floatSpeed);
    this.pos.add(p5.Vector.fromAngle(n * TWO_PI).mult(0.5));
    this.pos.add(this.vel);

    // Boundary wrap
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.y > height) this.pos.y = 0;
  }

  display() {
    push();
    translate(this.pos.x, this.pos.y);

    // Breathing pulse
    let pulse = sin(frameCount * 0.03 + this.phase) * 2;

    // Gold core (The Intelligence)
    fill(PALETTE.gold);
    noStroke();
    ellipse(0, 0, this.size + pulse);

    // Burgundy petals/aura (The Organic)
    stroke(PALETTE.burgundy);
    strokeWeight(1);
    noFill();

    // Draw stylized organic flora elements
    beginShape();
    for(let a = 0; a < TWO_PI; a += PI/4) {
      let r = this.size * (1.5 + sin(frameCount * 0.05 + a) * 0.5);
      vertex(cos(a) * r, sin(a) * r);
    }
    endShape(CLOSE);

    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  bgLayer = createGraphics(width, height);
  bgLayer.background(PALETTE.midnight);
}

function keyPressed() {
  if (key === 's' || key === 'S') saveCanvas('integration_neural_flora', 'png');
  if (key === 'r' || key === 'R') {
    nodes = [];
    setup();
  }
}
</script>
</body>
</html>
```

Prompt: ```javascript
let particles = [];
const numParticles = 800;
const coreRadius = 150;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(RGB);

  // Initialize consciousness streams
  for (let i = 0; i < numParticles; i++) {
    particles.push(new ConsciousnessStream());
  }
}

function draw() {
  background(10, 5, 15);

  rotateY(frameCount * 0.005);
  rotateX(frameCount * 0.003);

  // Draw the Structured Core (Digital Architecture)
  push();
  stroke(212, 175, 55, 150); // Deep Gold
  strokeWeight(1);
  noFill();

  // Geometric fractal lattice
  for(let i = 0; i < 5; i++) {
    push();
    rotateY(frameCount * 0.01 * i);
    box(coreRadius + (i * 20)); 
    pop();
  }
  pop();

  // Animate Fusion Flows
  particles.forEach(p => {
    p.update();
    p.display();
  });
}

class ConsciousnessStream {
  constructor() {
    this.init();
  }

  init() {
    // Start from random points in the digital void
    this.pos = createVector(random(-width, width), random(-height, height), random(-width, width));
    this.vel = createVector(0, 0, 0);
    this.acc = createVector(0, 0, 0);

    // Determine if this stream is Burgundy (Biological/Passion) or Gold (Digital/Intellect)
    this.type = random() > 0.5 ? 'burgundy' : 'gold';
    this.color = this.type === 'burgundy' ? color(128, 0, 32, 180) : color(212, 175, 55, 180);
    this.life = random(100, 300);
  }

  update() {
    // Pull towards the core (the singularity of Integration)
    let corePos = createVector(0, 0, 0);
    let dir = p5.Vector.sub(corePos, this.pos);
    dir.normalize();

    // Add orbital swirl (weaving effect)
    let swirl = createVector(-dir.y, dir.x, 0).mult(0.02);

    this.acc = dir.mult(0.01).add(swirl);
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.vel.limit(2);
    this.life -= 1;

    if (this.life <= 0 || this.pos.mag() < 20) {
      this.init();
    }
  }

  display() {
    stroke(this.color);
    strokeWeight(2);
    point(this.pos.x, this.pos.y, this.pos.z);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
